BZ020_PEAK = "丁巳运 ①用神火得巳禄地：满足；②运干丁官与火用呼应：满足；③否决三条：(i)未命中 (ii)未命中 (iii)未命中——满足3项称峰值；戊午运2项称次峰；余运均≤2项无否决命中。"
add("BZ-020", NT_BZ, ["八字（子平正统）"],
 "主断：仕宦中贵之命——杀印相生得用，任兵刑之官而立身（格局量级区间：下限仕宦衣食，依据杀印格成；上限中贵，依据身弱格力有限、官至州郡兵刑之任量级，不至极品）。运程逐段（顺行，约5岁起运）：甲寅运凶（财生杀克弱身、寅冲乏力，少年困）；乙卯运凶（财旺身不任，求学谋生耗）；丙辰运吉（丙杀透、辰印，杀印链通、入仕起步）；丁巳运吉·峰值（火用得地，任官典兵刑、权任最重在此段）；戊午运吉·次峰（印火并旺，位望续隆）；己未运平（己印、未冲丑，职务调动守成）；庚申运平（比劫帮身，申冲寅财，晚岁退居）；辛酉运平（金寒加重，安养终老）。交运带：丙辰运入运前后为仕途起步交接带，触发为辰土印填实化杀。关键结局：①子女——七杀丙火为子女星、透时得印化，子嗣有且能承家声；②病位——病字癸水寒湿，病在脾胃与肾寒水系；③破耗之因——早年财旺身弱因求财谋生耗损，中年后因仕途奔波耗财，不因赌败家；④一生高峰——丁巳运（约35–44岁，定值，运档坐标）。寿元中高，晚运金寒只压量级不断夭。",
 bz_basis(BZ020_MAIN, BZ020_FY, BZ020_PEAK), 0.62)
BZ021_MAIN = "特格扫描：从格未命中（己坐巳帝旺有根）、专旺未命中（火土不专局、水木并见）、燥极未命中（亥水有根、非夏令）；定常规格。运断主线：①格局——己土生戌月、坐巳临午，庚伤官年时双透而丁印年透，伤官配印成格；②用神——印火为用（化伤生身），官木疏土为相，亥水财冲巳印为病、得丁印坐镇为救之半；③定性——身旺印重，顺伤官配印之链论运，忌财破印。"
BZ021_FY = "病＝亥水妻财（年支，冲日支巳火用神印，病型破格）；药＝丁火正印（年干，坐镇制伤护身，虚浮于年位记药力中平）；扶抑取向＝喜印官、忌财水破印与金伤无印之运。"
BZ021_PEAK = "丙午运 ①用神火得午禄地：满足；②运干丙印呼应：满足；③否决三条：(i)未命中 (ii)未命中 (iii)未命中——满足3项称峰值；丁未运2项称次峰；余运均≤2项无否决命中（甲辰运辰冲戌为转折，已按作用表降为平）。"
add("BZ-021", NT_BZ, ["八字（子平正统）"],
 "主断：军政极贵之命——伤官配印成格，掌兵权而至元首级（格局量级区间：下限将帅之任，依据身旺格成；上限元首极贵，依据印用有力、大运火土长程助用）。运程逐段（逆行，原书标起运）：己酉运平（9–18，己比酉伤，泄秀求学）；戊申运平（19–28，军旅渐起、伤官无印压而未为峰）；丁未运吉·次峰（29–38，丁印填实，掌军权、地位跃升）；丙午运吉·峰值（39–48，印禄双临，权位登顶在此段）；乙巳运吉（49–58，乙官巳印官印相生，守成续掌）；甲辰运平（59–68，甲官、辰冲戌动摇根基，权力渐退）；癸卯运平（69–78，癸财破印之险被卯官泄化，退守安养）；壬寅运平（79–88，财官并见而身旺能任，寿终之段）。交运带：丁未入运前后为跃升交接带，触发为丁印透清。关键结局：①子女——官杀木为子女星、原局不透只藏亥甲，子嗣单薄而有子承继；②病位——病字亥水冲巳，火土燥而水激，病在心系与脾胃；③破耗之因——财水运段（癸卯、壬寅）因政局退守耗势，非钱财破败；④一生高峰——丙午运（39–48岁，定值，运档坐标）。寿元高，八十以外量级。",
 bz_basis(BZ021_MAIN, BZ021_FY, BZ021_PEAK), 0.7)
BZ022_MAIN = "特格扫描：从财格逐核——日主庚坐辰、丑皆印根，第①条无根不成立，从财未命中；专旺未命中；燥湿极端未命中；定常规格。运断主线：①格局——庚金生卯月财令，财旺生时上丁官，身弱财官重；②用神——印土护身、比金帮身任财为用，财太过为病；③定性——身弱先扶身任财，顺『帮身运发、财官运困』论运。"
BZ022_FY = "病＝卯亥妻财（月令与年支，财当令成势逾承载，病型太过，依 BZ-FY-2.2 财多身弱以财为病；承载门槛核为勉任偏不任：得地有辰丑印根、得生印存、余维皆弱）；药＝庚辛申酉金比劫与辰丑土印（帮身任财，原局只印根、比劫无透记药半力、待运补）；扶抑取向＝喜印比、忌财官再旺与食伤生财。"
BZ022_PEAK = "甲申运 ①帮身用神金得申禄地：满足；②运干甲财不呼应印比：不满足；③否决三条：(i)未命中 (ii)未命中 (iii)甲财透干而申为财之绝地不通根：未命中——满足2项；乙酉运同得2项，同分并列以先到之甲申为峰值、乙酉称次峰；余运均≤1项。"
add("BZ-022", TR_BZ, ["八字（子平正统）"],
 "主断：武人崛起之命——早年身弱财重困顿，中年金运帮身任财官，一跃为一方军阀之首（格局量级区间：下限地方豪强，依据财生官而格成于运；上限一方实际元首级，依据财官势大、峰值运帮身到位，不至全国正位）。运程逐段（顺行，约7岁起运）：庚辰运平（比印帮身，少年立足）；辛巳运平（辛劫、巳火官杀克身又冲亥，奔波受压）；壬午运凶（午官火旺克弱身、壬食只作半救，从军险困）；癸未运平（未印、癸伤见官，势力渐聚）；甲申运吉·峰值（申金帮身任财官，据地称雄在此段；其末年流年冲动病字有兵火暴亡之险，峰段与终局分列）；乙酉运平·次峰（酉金续势而乙财合庚，盛极转衰之带，设运程得续亦只守成）。交运带：癸未末至甲申初为崛起交接带，触发为申金填实帮身。关键结局：①子女——官杀丁火为子女星透时，子嗣多、长子能承军政之继；②病位与终局——病字在财不在脏腑定名，外伤兵火之险高于病亡（金弱火旺，肺金呼吸为次弱面）；③破耗之因——早年因财多身弱、为财招祸耗损，中年能任后聚而不散；④一生高峰——甲申运（约47–56岁，定值，运档坐标）。",
 bz_basis(BZ022_MAIN, BZ022_FY, BZ022_PEAK), 0.63)
BZ023_MAIN = "特格扫描：从格未命中（壬坐子有根、印比成党有自立之路，从势亦因财官有位不作专从）、专旺（润下）逐核——水虽三见而巳火财、丑土官并立相战，第③④条不全，未命中；定常规格。运断主线：①格局——壬水生巳月，子子癸水劫印并旺，身旺财官弱；②用神——巳火财、丑土官为用，子水比劫太过为病；③定性——身旺喜财官泄克，忌印比再助旺论运。"
BZ023_FY = "病＝子水劫财（日时两支，党众太过夺财压官，病型太过）；药＝巳火妻财与丑土正官（月支与年支，泄劫生官，巳被子水围而药力受压记中平）；扶抑取向＝喜财官食伤、忌印比金水。"
BZ023_PEAK = "庚寅运 ①用神火得寅长生地：满足；②运干庚印为忌不呼应：不满足；③否决三条：(i)未命中 (ii)未命中 (iii)庚印透干而寅为金绝地不通根：未命中——满足2项为诸运最高称峰值；丙戌运2项同分而后到，称次峰；己丑运丑合子水、官杀拘身，按转折运作用表定低运不入峰位。"
add("BZ-023", NT_BZ, ["八字（子平正统）"],
 "主断：将门少帅之命——青年即掌军权而显贵，中年一交官杀合身之运即长期受拘幽居，晚年得自由安养、寿极高（格局量级区间：下限将门显贵，依据印劫护身、财官有位；上限一方军政首脑，依据身旺无制、财官受压，不至元首正位）。运程逐段（逆行，约4岁起运）：壬辰运平（辰为水库官库，童年将门）；辛卯运平（卯食泄秀，少年习武从军）；庚寅运吉·峰值（24–33，寅食生财、青年掌军权、名位最盛在此段）；己丑运凶（34–43，己官、丑合子水劫，官杀合身主受拘——长期幽禁在此运起）；戊子运凶（44–53，子劫太过、幽居续段）；丁亥运平（54–63，丁财、亥劫，拘束渐松）；丙戌运吉·次峰（64–73，丙财戌官，晚年自由安养、名望回升）；乙酉运平（74–83，乙伤酉印，平静晚景）；甲申运平（84–93，甲食申印，高寿安养）；癸未运平（94以后，寿终之段在此运内）。交运带：庚寅末至己丑初为由峰转拘的交接带，触发为丑土合住子水用劫、官杀临身。关键结局：①子女——官杀土为子女星只藏丑中，子嗣有而缘分受幽运所隔，承继平；②病位——病字子水太过，病在肾与泌尿水系，然水旺印生反主寿长；③破耗之因——比劫夺财因同辈与政局变动失位耗财；④一生高峰——庚寅运（约24–33岁，定值，运档坐标）。寿元：极高，近百岁量级。",
 bz_basis(BZ023_MAIN, BZ023_FY, BZ023_PEAK), 0.66)
BZ024_MAIN = "特格扫描：从官杀逐核——乙坐丑有印根、壬子印生扶存，第①②条不成立未命中；专旺未命中；湿极未命中（午火有位）；定常规格。运断主线：①格局——乙木生申月，庚官申杀金旺攻身，壬子印贴身化杀，杀印相生勉成；②用神——印水为用、比木帮身为相，金杀太过为病；③定性——身弱以印化杀立身，顺印运贵、杀运困论运。承载门槛：不任偏勉任（得生印有力、余维弱）。"
BZ024_FY = "病＝庚申金官杀（月干与月支，得令党众克乙木，病型太过兼破格）；药＝壬子水印（时干与年支，化杀生身，印有根得力）；扶抑取向＝喜印比水木、忌金杀再旺与土财破印生杀。"
BZ024_PEAK = "癸亥运 ①用神水得亥旺地：满足；②运干癸印呼应：满足；③否决三条：(i)未命中 (ii)未命中 (iii)未命中——满足3项；甲子运同得3项，同分并列以先到之癸亥为峰值、甲子称次峰；余运均≤2项。"
add("BZ-024", TR_BZ, ["八字（子平正统）"],
 "主断：江湖领袖之命——不以官贵显、以社会声望与财势显：杀印相生使弱身得庇于权势又自成门户，中年水印运为一生权势声望之顶（格局量级区间：下限富商名流，依据印化杀格成；上限非官之极势、社会领袖级，依据官杀为病非格用、官位不在其途）。运程逐段（顺行，约6岁起运）：辛酉运凶（杀金叠旺克身，少年困厄）；壬戌运吉（壬印、戌藏印火，贵人庇护下起家）；癸亥运吉·峰值（26–35，印旺化杀，门户声势大成）；甲子运吉·次峰（36–45，甲劫帮身、子印续力，势望守顶）；乙丑运平（46–55，乙比、丑合子绊印，时局转而守成避居）；丙寅运平（56–65，丙伤见官、寅申冲杀，客居养病段）；丁卯运平（66以后，丁食卯比，晚年病弱客居、寿终之段在此前后）。交运带：乙丑运内为由盛转守交接带，触发为丑合子水用神印。关键结局：①子女——官杀金为子女星旺而多，子嗣众多；②病位——病字金杀克木、水寒金肃，病在肺与呼吸气道（哮喘类为倾向表述）；③破耗之因——晚年因病与避居异地耗财，兼食伤运泄身；④一生高峰——癸亥运（约26–35岁）为峰值、甲子运次峰（定值，运档坐标）。",
 bz_basis(BZ024_MAIN, BZ024_FY, BZ024_PEAK), 0.64)
BZ025_MAIN = "特格扫描：从格未命中（丁坐酉虽败、甲卯印根生扶存）、专旺未命中、燥极未命中（癸水有位、非夏令极燥）；定常规格。运断主线：①格局——丁火生戌月，甲印年时（月干甲、时支卯）双扶，癸七杀时透，杀印相生兼戌土食伤泄秀生酉财，艺业取象之格；②用神——印木为用（化杀生身）、比火为相，癸水杀为病；③定性——身弱喜印比，顺印运名显、财运耗身论运。"
BZ025_FY = "病＝癸水七杀（时干，克丁火弱身，病型破格）；药＝甲卯木印（年干月干与时支，化杀生身，印根深得力）；扶抑取向＝喜印比木火、忌财金破印与水杀再旺。"
BZ025_PEAK = "己卯运先核：③否决 (i) 运干己合绊用神之干甲印——命中，己卯运按伪峰处置、资格取消；丁丑运 ①用神木于丑无地：不满足；②运干丁比呼应扶身：满足；③否决三条全未命中：满足——2项；戊寅运同得2项，同分并列以先到之丁丑为峰值、戊寅称次峰；余运均≤2项。"
add("BZ-025", NT_BZ, ["八字（子平正统）"],
 "主断：艺业极盛之命——以技艺（梨园行）名满天下，名大于官、富而文雅（格局量级区间：下限艺坛名宿，依据杀印相生格成、食伤泄秀；上限行业宗师级声望，依据印用有力而官星只作杀不作权位正途）。运程逐段（顺行，约5岁起运）：乙亥运吉（乙印、亥杀印相生，学艺成名之始）；丙子运平（丙比、子杀冲午，青年奔波而名渐起）；丁丑运吉·峰值（25–34，丁比帮身、丑为食伤库泄秀，声名大成在此段）；戊寅运吉·次峰（35–44，戊食泄秀、寅印，名望续顶、海外扬名之段）；己卯运平（45–54，己食、卯印，本有成峰之象而己合甲印——伪峰，只作名高运平）；庚辰运平（55–64，庚财、辰酉合金耗印，守成）；辛巳运平（65以后，辛财巳比，晚年名存、寿终之段在此运内）。交运带：丁丑入运前后为成名交接带，触发为丁火比肩帮身得地。关键结局：①子女——官杀癸水为子女星透时，子嗣有且承其艺业家声；②病位——病字癸水克丁火，病在心系与目力；③破耗之因——财金运（庚辰、辛巳）破印耗名耗财，非败家之破；④一生高峰——丁丑运（约25–34岁）为峰值、戊寅运次峰（定值，运档坐标）。寿元中高，六十以外量级。",
 bz_basis(BZ025_MAIN, BZ025_FY, BZ025_PEAK), 0.64)
BZ026_MAIN = "特格扫描：从格未命中（丙坐戌巳有火根、乙印生扶存）、专旺未命中、寒极逐核——丑月而火有戌巳根、丙透时外有根，不作无暖，未命中；定常规格。运断主线：①格局——丙火生丑月寒湿，乙正印月透、癸正官时透，官印相生而身弱；②用神——印木与火调候并用，丑中癸水寒湿为病之半；③定性——寒局先调候，顺印火运名显、寒金水运困论运。"
BZ026_FY = "病＝癸水正官兼丑寒湿（时干与月支，寒水克丙弱火，病型壅塞兼太过之半）；药＝乙木正印与巳戌火根（月干与日时支，印化官生身、火暖局，药有根得力）；扶抑取向＝喜印比木火、忌金水寒湿再增。"
