# ===== writer =====
import json, os
BASE="/home/hatch/workspace/divination/benchmark/phase3/runs/round76"
b=json.load(open(f"{BASE}/batches.json"))
ids=b["B01"]+b["B02"]+b["B03"]
assert len(ids)==60, len(ids)
missing=[c for c in ids if c not in P]
assert not missing, missing
os.makedirs(f"{BASE}/predictions", exist_ok=True)
written=[]
for cid in ids:
    d=P[cid]
    basis = d["trad_line"]+"\n"+"systems_used: "+", ".join(d["systems"])+"\n"+d["extra"]
    trig = d["trig"] if d["trig"] is not None else dict(changed_main=False, reserve_used=False, disputed=False)
    trig_full = dict(changed_main=trig["changed_main"], reserve_used=trig["reserve_used"], disputed=trig["disputed"], reason=("卡面无全盘、取用与旺衰多据卡面自述状态判读，存疑留痕" if trig.get("disputed") else ("终局应验位取伏神参与判定，留痕" if trig.get("reserve_used") else "")))
    obj=dict(case_id=cid, prediction_text=d["pred"], basis=basis, confidence=d["conf"], trigger=trig_full)
    path=f"{BASE}/predictions/{cid}.json"
    with open(path,"w") as f:
        json.dump(obj,f,ensure_ascii=False,indent=1)
    written.append((path, os.path.getsize(path)))
cm=sum(1 for c in ids if P[c]["trig"] and P[c]["trig"]["changed_main"])
ru=sum(1 for c in ids if P[c]["trig"] and P[c]["trig"]["reserve_used"])
di=sum(1 for c in ids if P[c]["trig"] and P[c]["trig"]["disputed"])
print("written",len(written),"changed_main",cm,"reserve_used",ru,"disputed",di)
for p,s in written: print(p,s)
